function GEOSUM(r, s):
    total <- 0 ; term <- 1
    repeat s times:
        term <- term * r ; total <- total + term
    return total                       # = r + r^2 + ... + r^s

function MIN-SAMPLE-POINTS(a, b, N):
    require a >= 1 and b >= 1
    s <- 0
    while GEOSUM(a*b, s) < N:          # capacity is strictly increasing in s
        s <- s + 1
    return s                           # least s with N <= Sigma(ab, s)

function OPTIMAL-GRID(a, b, s):
    G <- empty list
    for j <- 0 to s-1:
        append b * (GEOSUM(a*b, j) + 1) to G
    return G                           # the unique capacity-optimal grid

function DESIGN-SWEEP(a, b, N):
    s <- MIN-SAMPLE-POINTS(a, b, N)
    return (s, OPTIMAL-GRID(a, b, s), GEOSUM(a*b, s))

function LOCALISES(G, a, b, N):        # O(|G| * N) verification
    for c <- 1 to N:
        if no g in G satisfies (g <= b*c and c <= a*g): return false
    return true

