"""Construction of the capacity-optimal sampling grid at tolerance (a, b)."""

from __future__ import annotations

from typing import List, Sequence


def geo_sum(r: int, s: int) -> int:
    """Sigma(r, s) = r + r^2 + ... + r^s, the exact capacity of s points at product r."""
    total, term = 0, 1
    for _ in range(s):
        term *= r
        total += term
    return total


def min_sample_points(a: int, b: int, n: int) -> int:
    """Least number of sample points that localises [1, n] at tolerance (a, b).

    Equals the least s with n <= Sigma(a*b, s).  For a*b >= 2 this is
    O(log_{ab} n); for a*b == 1 (no tolerance at all) it is n.
    """
    if a < 1 or b < 1:
        raise ValueError("tolerances must be at least 1")
    s = 0
    while geo_sum(a * b, s) < n:
        s += 1
    return s


def optimal_grid(a: int, b: int, s: int) -> List[int]:
    """The unique capacity-optimal (a, b)-localising grid with s points.

    Point j is b * (Sigma(ab, j) + 1); it serves exactly the budgets
    [Sigma(ab, j) + 1, Sigma(ab, j+1)], so the s points tile [1, Sigma(ab, s)].
    """
    return [b * (geo_sum(a * b, j) + 1) for j in range(s)]


def design_sweep(a: int, b: int, n: int) -> tuple[int, List[int], int]:
    """Full design: minimal point count, the grid, and the capacity it achieves."""
    s = min_sample_points(a, b, n)
    return s, optimal_grid(a, b, s), geo_sum(a * b, s)


def localises(grid: Sequence[int], a: int, b: int, n: int) -> bool:
    """Verification: does `grid` serve every budget in [1, n] at tolerance (a, b)?"""
    return all(any(g <= b * c and c <= a * g for g in grid) for c in range(1, n + 1))


if __name__ == "__main__":
    for (a, b, n) in [(1, 2, 30), (1, 2, 64), (2, 2, 340), (1, 4, 340), (3, 2, 1000)]:
        s, grid, cap = design_sweep(a, b, n)
        assert localises(grid, a, b, n)
        print(f"tolerance ({a},{b}), target [1,{n}]: {s} points {grid}, capacity {cap}")

"""Exhaustive verification of sweep capacity and of the uniqueness of the optimum."""

from __future__ import annotations

from itertools import combinations
from typing import List, Sequence, Tuple


def geo_sum(r: int, s: int) -> int:
    total, term = 0, 1
    for _ in range(s):
        term *= r
        total += term
    return total


def localises(grid: Sequence[int], a: int, b: int, n: int) -> bool:
    return all(any(g <= b * c and c <= a * g for g in grid) for c in range(1, n + 1))


def reach(grid: Sequence[int], a: int, b: int, n_max: int) -> int:
    """Largest n <= n_max with grid an (a,b)-localiser of [1, n]."""
    n = 0
    while n + 1 <= n_max and localises(grid, a, b, n + 1):
        n += 1
    return n


def brute_force_capacity(
    a: int, b: int, s: int, n_max: int
) -> Tuple[int, List[List[int]]]:
    """Search all s-subsets of [1, n_max]; return the capacity and every optimum.

    Complexity: C(n_max, s) subsets, each tested in O(s * n_max), so this is a
    toy-scale check only -- which is exactly why the closed form Sigma(ab, s)
    and the uniqueness theorem are worth having.
    """
    best, optima = 0, []
    for grid in combinations(range(1, n_max + 1), s):
        n = reach(grid, a, b, n_max)
        if n > best:
            best, optima = n, [list(grid)]
        elif n == best and n > 0:
            optima.append(list(grid))
    return best, optima


if __name__ == "__main__":
    for (a, b, s, n_max) in [(1, 2, 2, 12), (1, 2, 3, 20), (1, 3, 2, 18), (2, 2, 2, 30)]:
        cap, optima = brute_force_capacity(a, b, s, n_max)
        predicted = geo_sum(a * b, s)
        print(f"(a,b)=({a},{b}), s={s}: capacity {cap} (theory {predicted}), "
              f"optima {optima}")
        assert cap == predicted and len(optima) == 1
    print("capacity formula and rigidity confirmed by exhaustive search.")
